// Generated by tools/gen-hints.mjs from stage/hints/*.md. Do not edit.
export const hintFiles: string[] = ["calendar.md","chrome.md","clock.md","gmail.md","home.md","maps.md","messages.md","settings.md","spotify.md","whatsapp.md","youtube.md"];
export const hints: string[] = [
  "# Calendar (Samsung Calendar com.samsung.android.calendar, or Google Calendar com.google.android.calendar)\n\nOpening it: the icon label is \"Calendar\". Check the screen's `app` to know which one opened. The labels below cover both, with Samsung first.\n\n- **What's on today or tomorrow:** both apps open on today. Event rows show as text with the time and title, such as \"10:00 AM Team standup\". Read them out rather than tapping. For tomorrow, `swipe left` once in day view, or tap the date in month view.\n- **Change the view:** Samsung has a menu button (\"Open navigation drawer\" or \"≡\") with \"Year\", \"Month\", \"Week\", \"Day\", \"Schedule\". Google has the same items in its menu. \"Schedule\" lists the upcoming events, which is the easiest to read.\n- **New event:** tap the \"+\" button, bottom right (description \"Add event\" or \"Create\"). Google may then ask \"Event\", \"Task\", \"Birthday\": tap \"Event\". Tap the \"Title\" field and `type`. Then set the start time: tap the time shown under \"Starts\" (Samsung) or next to the date (Google), and pick from the clock or list. Tap \"Save\" at the top right (Google) or bottom (Samsung).\n- **Open an event:** tap its row. \"Edit\" (a pencil) and \"Delete\" (a bin, or under \"More options\") are at the top.\n\n## What goes wrong\n\n- Time pickers differ a lot between apps and phones. After each tap, read the screen again and look for the time you want as text before tapping \"Save\".\n- An event with no time set becomes an all-day event. Check the \"All day\" switch is off when the user gave a time.\n- Several calendars (personal, work) can show a calendar picker. Leave the default unless the user named one.\n- Never delete or edit events unless asked. If you open an event by mistake, `key back`.\n",
  "# Chrome (com.android.chrome)\n\nSamsung phones also ship \"Internet\" (com.sec.android.app.sbrowser). It works much the same; use whichever browser the user named.\n\n- **Address bar** (checked on the S21): at the top. Empty, it's a field whose hint is \"Search Google or type URL\". `{\"text\":\"Search Google or type URL\"}` finds it, and so does `{\"text\":\"Search Google\"}`. With a page open, it shows the page's address. To its right are the tabs button, whose description is \"See N tabs\" (such as \"See 16 tabs\", so match `{\"text\":\"tabs\"}`), and \"Customize and control Google Chrome\" (the three dots menu). The new tab page also has \"Start voice search\", \"Ask AI Mode\", a Lens button and \"Open the home page\". Ignore those unless asked.\n- **Search or open a site:** tap the address bar → `type` the search or the address with no `on` → `key enter`.\n- **Results and pages:** a web page's links show up as nodes with their visible text. Tap the title of a result or the words of a link, such as `{\"text\":\"Opening hours\"}`. To read further down, `swipe up`.\n- **Go back a page:** `key back`.\n- **New tab, bookmarks, history:** tap \"Customize and control Google Chrome\" → \"New tab\", \"Bookmarks\" or \"History\".\n\n## What goes wrong\n\n- Many web buttons have no label. Tap the visible text next to them, or the link text. If nothing on screen fits, say so rather than tapping a pixel at random.\n- Cookie banners (\"Accept all\", \"Reject all\") cover the page. Tap \"Reject all\" if it's there, otherwise \"Accept all\".\n- \"Sign in to Chrome\", \"Open in app?\" and notification prompts: tap \"No thanks\", \"Stay in Chrome\" or \"Use without an account\".\n- The address bar hides while you scroll down. `swipe down` a little to bring it back.\n- The keyboard covers the bottom half of the page. `key back` once hides it. A second `key back` leaves the page.\n",
  "# Clock (Samsung, com.sec.android.app.clockpackage)\n\nOpening it: the icon label is \"Clock\". It's often in a \"Samsung\" folder, or in the app drawer.\n\n- **Tabs** along the bottom: \"Alarm\", \"World clock\", \"Stopwatch\", \"Timer\". Tap a tab by name.\n- **New alarm:** \"Alarm\" tab → tap \"Add alarm\" (a \"+\" at the top right) → the time picker shows hour and minute wheels, each an editable field. Tap the hour, `type` the number, then the minute and `type` again. Set \"AM\" or \"PM\" if shown. Then tap \"Save\" at the bottom.\n- **Alarm name:** on the same screen, the \"Alarm name\" field takes text, such as \"Gym\".\n- **Turn an alarm on or off:** each alarm row has a switch at its right edge. Its description includes the time, such as \"7:00 AM\". Tap the switch, not the row: tapping the row opens it for editing.\n- **Timer:** \"Timer\" tab → hours, minutes and seconds fields → `type` into each → tap \"Start\".\n- **Stopwatch:** \"Stopwatch\" tab → \"Start\", then \"Lap\" or \"Stop\".\n\n## What goes wrong\n\n- Typing into the time wheels can need a tap first to make them editable. If `type` fails with `not_editable`, tap the number and try again.\n- 24-hour phones show no \"AM\"/\"PM\". Use 24-hour time.\n- After \"Save\", a short message like \"Alarm set for 8 hours from now\" shows. That means it worked. Tell the user the time it says.\n- Don't delete alarms unless asked. A long press selects rows for deleting. `key back` leaves that mode.\n",
  "# Gmail (com.google.android.gm)\n\nLabels checked on the S21 (One UI, Android 15).\n\n- **Inbox:** the top search field is an empty field whose hint is \"Search in mail\". `{\"text\":\"Search in mail\"}` still finds it. To its left is \"Open navigation drawer\". To its right is the account picture (\"Signed in as …\"). Bottom right is a \"Compose\" button. The tab bar at the bottom has \"Mail\" and \"Meet\". Stay on \"Mail\".\n- **Email rows:** each row is one tappable node whose text is \"Sender, Subject, preview…\" (such as \"Sarah Chen, Running late, can we push to 3?\"). Inside it are separate, non-tappable text nodes for the sender, subject and preview. The newest email is at the top. Tap the row by the sender's name, such as `{\"text\":\"Sarah Chen\"}`.\n- **Open email:** the sender is near the top, with a small \"Reply\" icon beside it. Before replying, check that the sender is the person the user named. At the bottom of the message are \"Reply\" and \"Forward\". \"Reply all\" is not there: it's under \"More options\". On a long email you may need to `swipe up`. Top right are \"Archive\", \"Delete\", \"Mark unread\" and \"More options\".\n- **Reply:** open the email → tap \"Reply\" → the message body gets the focus by itself → `type` the text with **no `on`** → tap \"Send\" (top right, description \"Send\"). The subject shows \"Re: <subject>\". The body has no label, so never target it by text.\n- **New email:** tap \"Compose\" → in the \"To\" field, type a name or address, then tap the suggested contact → tap \"Subject\" and type → tap below the subject to focus the body and type → tap \"Send\".\n- **Search:** tap \"Search in mail\" → type the search → `key enter` → the results list.\n\n## What goes wrong\n\n- The keyboard can hide \"Reply\", \"Forward\" and the bottom of the body. \"Send\" is always at the top, so it stays reachable. If you need something under the keyboard, `key back` once to hide it.\n- An email that's part of a conversation opens the whole thread. \"Reply\" answers the last message.\n- Suggested-reply buttons (\"Sounds good!\", \"Thanks!\") sit near \"Reply\". Don't tap them unless one says exactly what the user wants.\n- Several accounts: the account picture switches between them. Check you're in the right inbox before searching.\n- After sending, a \"Sent\" message with \"Undo\" shows for a few seconds. Never tap \"Undo\".\n- **Throwing away a reply:** \"More options\" → \"Discard\". `key back` can save a draft instead. Only discard if the user cancelled. Never leave drafts behind.\n",
  "# Samsung home screen (One UI launcher)\n\nThe screen's app is `com.sec.android.app.launcher`. You see it after `key home`.\n\n- **App icons** show up as nodes whose `text` is the app's name under the icon, such as \"Gmail\", \"Messages\" or \"Chrome\". They are tappable. Tap the label to open the app.\n- **The dock** is the row at the very bottom (high `top` values, around 2000 to 2300 on a 2400-pixel-tall screen). It holds the same 4 or 5 apps on every page, usually Phone, Messages, Internet or Chrome, and Camera. Check it first.\n- **Pages:** the home screen has several pages side by side. To see the next page, `swipe left`. To go back a page, `swipe right`. After each swipe, read the screen again. If the labels didn't change, you're on the last page.\n- **Page dots:** a small row of dots above the dock shows which page you're on. It may have a description such as \"Page 2 of 3\". Use it to know how many pages are left.\n- **Folders** look like an app icon with a name such as \"Google\" or \"Social\". Gmail is often inside a folder named \"Google\". Tap the folder name to open it. Its apps then show up as nodes over the home screen. Tap the app inside. If the app isn't there, `key back` closes the folder.\n- **App drawer** (every installed app, A to Z): from the home screen, `swipe up` from the middle of the screen. It has a search field at the top (\"Search\" or \"Search phone\"). Use it as a fallback when the app isn't on any home page.\n- **Widgets** (clock, weather, Google search bar) also show up as nodes. Ignore them. Tapping the Google search bar opens a search, not an app.\n\n## What goes wrong\n\n- A swipe that starts on a widget can scroll the widget instead of changing the page. If the screen didn't change, swipe again from another spot, such as `{\"x\":540,\"y\":1500}`.\n- `swipe down` on the home screen opens the notification shade. `key back` closes it.\n- A long press opens an edit menu (\"Remove\", \"Select\", \"Edit\"). If you see those words, `key back`.\n- Labels can be cut short (\"Messa…\"). Match on the start of the name.\n- If the screen shows a lock screen, or anything that isn't the launcher after `key home`, say so. Don't try to unlock it.\n",
  "# Google Maps (com.google.android.apps.maps)\n\n- **Main screen:** the search box at the top is a field described \"Search here\". To its right are a microphone (\"Voice search\") and the account picture. Below it is a row of chips (\"Restaurants\", \"Coffee\", \"Groceries\", \"Home\"). The bottom tabs are \"Explore\", \"You\" (its description may add \"New updates in You\") and \"Contribute\".\n- **Find a place:** tap \"Search here\" → `type` the search, such as \"coffee near me\" → `key enter`. A list of results slides up from the bottom. Each row has the name, rating, distance and whether it's open.\n- **Open a place:** tap its name. A sheet shows its details with buttons \"Directions\", \"Start\", \"Call\", \"Save\" and \"Share\". The address and opening hours are further down; `swipe up` on the sheet to read them.\n- **Directions:** on a place's sheet, tap \"Directions\" → pick the travel mode from the row of tabs (\"Driving\", \"Transit\", \"Walking\") → the route and time show at the bottom. Only tap \"Start\" if the user asked to be navigated there.\n- **Back to the map:** `key back` closes a place, then clears the search. One more `key back` leaves Maps.\n\n## What goes wrong\n\n- The map itself is one big view with no labels. Never tap the map. Work with the search box, the chips and the results list.\n- The results list starts half open. `swipe up` on it to see more rows, `swipe down` to see the map.\n- Results marked \"Sponsored\" or \"Ad\" come first. Skip them unless the user named that place.\n- Location prompts (\"Turn on location accuracy\", \"Allow Maps to access this device's location?\"): tap \"While using the app\" or \"No thanks\". Never change other settings.\n- If the user said a place name, check the result's name and area match it before giving directions or calling.\n",
  "# Messages (com.google.android.apps.messaging or com.samsung.android.messaging)\n\nOn the S21 the default is **Google Messages** (`com.google.android.apps.messaging`). Samsung Messages is also installed. The `app` field of the screen tells you which one is open. Labels are close in both.\n\n- **Conversation list:** one row per person, holding the name and the last message. The newest is at the top. Tap a row by the name, such as `{\"text\":\"Sarah Chen\"}`. At the top are \"Search messages\" and the account picture. The new-message button is bottom right: \"Start chat\" in Google Messages, \"Compose new message\" (a pencil) in Samsung Messages. Google Messages also has a \"Gemini\" button just above \"Start chat\". It's a chatbot, so never tap it.\n- **Open conversation:** messages fill the screen, newest at the bottom. The text field is at the bottom: \"Text message\", \"RCS message\" or \"Chat message\" in Google Messages, \"Enter message\" in Samsung Messages. The send button is to its right and only appears once there is text; its description starts with \"Send\".\n- **Text someone you've texted before:** tap their row → tap the text field → `type` the text → tap the button whose description starts with \"Send\".\n- **Text someone new:** tap \"Start chat\" (or \"Compose new message\") → `type` the name into the \"To\" field → tap the matching contact → tap the text field → `type` → tap \"Send\".\n\n## What goes wrong\n\n- Before you type, the send spot holds a microphone (\"Voice message\"). Tapping it records audio. Only tap \"Send\" after the text is in.\n- A contact with several numbers shows a list (\"Mobile\", \"Home\", \"Work\"). Pick \"Mobile\".\n- \"Set as default SMS app?\", \"Turn on chat features\" and similar cards: tap \"Not now\" or \"Cancel\". Never change defaults.\n- `key back` with text in the field leaves it as a draft. Send it, or clear it if the user cancelled.\n- Check the name at the top of the conversation before sending. Groups and contacts can share first names.\n",
  "# Settings (com.android.settings, Samsung One UI)\n\n- **Main list:** a big \"Settings\" title, a search icon described \"Search settings\" at the top right, the account row, then sections: \"Connections\" (subtitle \"Wi-Fi • Bluetooth • SIM manager\"), \"Connected devices\", \"Modes and Routines\", \"Sounds and vibration\", \"Notifications\", \"Display\" (below the first screen), \"Battery\", \"Lock screen\", \"Security and privacy\", \"Location\", \"Apps\", \"General management\", \"Accessibility\", \"Software update\", \"About phone\". `swipe up` to see the lower ones.\n- **Fastest way to anything:** tap \"Search settings\" → `type` the setting's name, such as \"dark mode\" or \"brightness\" → tap the matching result.\n- **Where things are:** Wi-Fi, Bluetooth and Airplane mode are under \"Connections\". Dark mode and brightness are under \"Display\". Volume and ringtone are under \"Sounds and vibration\". Do not disturb is under \"Modes and Routines\" or \"Notifications\", depending on the version.\n- **Switches:** a row's text is the setting's name, and its switch is often a separate node described \"On\" or \"Off\". Tap the switch, then read the screen to see it changed. Some rows open a page instead of switching.\n- **Quick settings:** `key notifications` opens the shade, and a second `swipe down` shows the tiles (\"Wi-Fi\", \"Bluetooth\", \"Flashlight\", \"Do not disturb\"). Each tile's description holds its state, such as \"Wi-Fi, On\". Tap a tile to switch it.\n\n## What goes wrong\n\n- These change the real phone. Never turn off Wi-Fi, mobile data, Bluetooth (the earbuds use it), Airplane mode, accessibility services or notification access unless the user said so in plain words, and say what will happen first. Bobby can lose his connection.\n- Names differ between One UI versions. If a section isn't where you expect, use \"Search settings\".\n- A page that asks for a PIN, pattern or fingerprint: stop and tell the user. Never guess.\n- `key back` goes up one level. `key home` leaves Settings.\n",
  "# Spotify (com.spotify.music)\n\n- **Bottom tabs:** described \"Home, Tab 1 of 5\", \"Search, Tab 2 of 5\", \"Your Library, Tab 3 of 5\", \"Premium, Tab 4 of 5\". Target them by name, such as `{\"text\":\"Search, Tab\"}`. A plain `{\"text\":\"Search\"}` can hit something else first. The tab nodes aren't marked tappable (their containers are), but tapping them works. The mini-player bar (\"Now Playing Bar\") sits just above the tabs while something is playing.\n- **Find music:** tap the \"Search\" tab → tap the field \"What do you want to listen to?\" → `type` the song, artist or playlist with no `on` → tap the matching row. Chips below the field (\"Songs\", \"Artists\", \"Playlists\", \"Albums\", \"Podcasts\") narrow the results.\n- **Result rows:** each row holds the title and the kind, such as \"Song • Taylor Swift\" or \"Artist\". Tapping a song row plays it. Tapping an artist, album or playlist opens its page.\n- **Artist, album or playlist page:** the big green round button near the top is \"Play\" (its description may be \"Play\" or \"Play playlist\"). \"Shuffle\" sits next to it. Tap \"Play\".\n- **Pause, skip:** the mini-player has \"Pause\" (or \"Play\") at its right. Tap the track name on the mini-player to open the full player, with \"Previous\", \"Pause\", \"Next\", \"Shuffle\" and \"Repeat\".\n\n## What goes wrong\n\n- On a free account, ads and \"Premium\" cards pop up. Tap \"Dismiss\", \"Not now\" or \"Close\". Some songs may play shuffled instead of the one asked for; tell the user.\n- Never tap \"Connect to a device\" or \"Devices available\". It moves the sound to another speaker.\n- Home cards are long combined descriptions. Match on the artist or playlist name.\n- If nothing plays after \"Play\", check for a pop-up covering the screen, then read the mini-player.\n",
  "# WhatsApp (com.whatsapp)\n\n- **Chat list:** tabs along the bottom are \"Chats\", \"Updates\", \"Communities\" and \"Calls\". Stay on \"Chats\" (its description adds the unread count, such as \"Chats, 3 new notifications\"). At the top is a search bar (\"Ask Meta AI or Search\") and \"More options\". Each row holds the contact or group name, the last message, the time and maybe \"2 unread messages\". The round picture on the left is described \"<name> picture\". Tap a row by the name, such as `{\"text\":\"Sarah Chen\"}`.\n- **New chat:** the green button bottom right, description \"New chat\". It opens the contact list with \"Search name or number\" at the top.\n- **Open chat:** the name is at the top, with \"Video call\" and \"Voice call\" to its right. The text field at the bottom has the hint \"Message\", with \"Emoji\" to its left and \"Attach\" and \"Camera\" to its right. The round button at the far right is \"Voice message\" until you type, then it becomes \"Send\".\n- **Send a message:** on \"Chats\", tap the person's row (if it isn't visible, tap the search bar, `type` the name and tap the result under \"Chats\" or \"Contacts\") → tap \"Message\" → `type` the text → tap \"Send\".\n- **Reply to one message:** `long_press` the message → tap \"Reply\" in the top bar → `type` → tap \"Send\". A normal message is usually enough.\n\n## What goes wrong\n\n- Search results can include \"Meta AI\". It's a chatbot, not a contact. Never tap it.\n- Tapping \"Voice message\" before typing starts a recording. Only tap \"Send\" once the text is in the field.\n- Never tap \"Video call\" or \"Voice call\" unless the user asked for a WhatsApp call.\n- Pop-ups about backup, updates or notifications: tap \"Not now\", \"Skip\" or \"Later\".\n- Check the name at the top of the chat before sending. Groups and contacts can share first names.\n",
  "# YouTube (com.google.android.youtube)\n\nOpening it: the icon label is \"YouTube\". It's often in a \"Google\" folder.\n\n- **Search:** tap \"Search\" (a magnifier at the top right) → the field \"Search YouTube\" gets the focus → `type` the search → `key enter`. Results are rows whose description holds the title, channel, views and length, such as \"Lo-fi beats to study to - 2 hours - ChillHop - 3M views\".\n- **Play a video:** tap the result's row by a distinctive word from its title. The video starts in a player at the top.\n- **Player controls:** tap the video once to show the controls. They hide again after a few seconds, so read the screen and tap straight away. They are \"Pause video\" / \"Play video\", \"Next video\", and \"Enter fullscreen\". `key back` shrinks the player into a mini player at the bottom.\n- **Bottom tabs:** \"Home\", \"Shorts\", \"Subscriptions\", \"You\". Stay out of \"Shorts\" unless asked.\n\n## What goes wrong\n\n- Ads: a \"Skip\" or \"Skip ad\" button can show after a few seconds. Tap it when you see it. Don't tap the ad itself (\"Visit advertiser\", \"Learn more\").\n- The first rows can be ads (\"Sponsored\") or Shorts. Skip those and pick a normal video row.\n- Rotating to fullscreen changes `size`. Read the screen again before tapping by position.\n- Don't like, subscribe, comment or share unless the user asked.\n"
];
